+    bL0TensorPingPong = tmpBufL0B.Get<KV_T>();
+    // L0C
+    pipe->InitBuffer(tmpBufL0C, L0C_PP_SIZE * 2); // 128K
+    cL0TensorPingPong = tmpBufL0C.Get<MM_OUT_T>();
+}
