+template <typename FusedSparseAttentionOverlapTraits>
+__aicore__ inline bool
+FusedSparseAttentionOverlapVectorService<FusedSparseAttentionOverlapTraits>::IsSelectionPlanHit(
+    int16_t planValue) const
+{
+    return planValue > 0;
+}
