+template <typename FusedSparseAttentionOverlapTraits>
+__aicore__ inline bool
+FusedSparseAttentionOverlapVectorService<FusedSparseAttentionOverlapTraits>::IsSelectionPlanUpdate(
+    int16_t planValue) const
+{
+    return planValue < 0;
+}
