+        constInfo.gSize = this->sharedParams.gSize;
+        constInfo.s1Size = this->sharedParams.s1Size;
+        constInfo.dSizeV = 512;
+        constInfo.needInit = this->sharedParams.needInit;
+        constInfo.returnSoftmaxLse = false;
