+template <typename CubeBlockType, typename VecBlockType>
+__aicore__ inline void FusedSparseAttentionOverlapKernelMla<CubeBlockType, VecBlockType>::InitUniqueConstInfo()
+{
+    // bsize + 1-> bsize
+    this->constInfo.actualSeqLenSize = this->sharedParams.bSize;
+    this->constInfo.actualSeqLenKVSize = this->sharedParams.bSize;
+}
