+template <typename CubeBlockType, typename VecBlockType>
+__aicore__ inline void FusedSparseAttentionOverlapKernelMla<CubeBlockType, VecBlockType>::Process()
+{
+    // Both Cube and Vector must call SyncAll.
+    if (this->sharedParams.needInit) {
+        SyncAll<false>();
+    }
+
+    ProcessMainLoop();
+}
+
+template <typename CubeBlockType, typename VecBlockType>
+__aicore__ inline void FusedSparseAttentionOverlapKernelMla<CubeBlockType, VecBlockType>::ProcessMainLoop()
+{
+    bool hasLoad = aicIdx < usedCoreNum;
+    if (!hasLoad) {
+        if ASCEND_IS_AIV {
+            if constexpr (IS_SPLIT_G) {
+                for (int64_t loopCnt = 0; loopCnt < maxS2LoopCnt; loopCnt++) {
+                    CrossCoreSetFlag<FSA_ARCH35_SYNC_MODE0, PIPE_MTE3>(15);
+                    CrossCoreWaitFlag<FSA_ARCH35_SYNC_MODE0, PIPE_MTE3>(15);
+                }
+            }
+        }
+        return;
+    }
+
+    // Adapt core partitioning to a left-closed, right-open interval.
+    uint32_t bIdx = constInfo.bN2End / constInfo.n2Size;
+    uint32_t actS1Size = GetBalanceActualSeqLengths(actualSeqLengthsQGm, bIdx);
+    uint32_t gS1max = actS1Size;
+    if (constInfo.gS1End + 1 < gS1max) {
+        /* When constInfo.gS1End != gS1max, increment gS1End by one and leave bN2End unchanged. */
+        constInfo.gS1End = constInfo.gS1End + 1;
+    } else {
+        /* When constInfo.gS1End == gS1max, advance bN2End and set gS1End to 0 to represent the end. */
+        constInfo.bN2End = constInfo.bN2End + 1;
+        constInfo.gS1End = 0;
+    }
+
+    // Core-partition information
+    uint32_t bN2StartIdx = constInfo.bN2Start;
+    uint32_t bN2EndIdx = constInfo.bN2End;
+    uint32_t gS1StartIdx = constInfo.gS1Start;
+    uint32_t nextGs1Idx = constInfo.gS1End;
+    uint32_t s2StartIdx = 0;
+    uint32_t s2EndIdx = 0;
+    uint32_t s2LoopLimit = 0;
+
+    if (nextGs1Idx != 0) {
+        bN2EndIdx++;
+    }
+
+    int64_t taskId = 0;
+    bool notLast = true;
+    RunInfo runInfo[3];
+    RunParamStr runParam;
+    int64_t multiCoreInnerIdx = 1;
+
+    for (int64_t bnIdx = bN2StartIdx; bnIdx < bN2EndIdx; bnIdx++) {
+        bool lastBN = (bnIdx == bN2EndIdx - 1);
+        runParam.boIdx = bnIdx;
+        runParam.n2oIdx = 0;
+        ComputeParamBatch<TEMPLATE_INTF_ARGS>(runParam, this->constInfo,
+            this->actualSeqQlenAddr, this->actualSeqKvlenAddr);
+        ComputeS1LoopInfo<TEMPLATE_INTF_ARGS>(runParam, this->constInfo, lastBN, nextGs1Idx, gS1StartIdx);
+
+        int64_t gS1LoopEnd = lastBN ? (runParam.gs1LoopEndIdx + PRELOAD_NUM) : runParam.gs1LoopEndIdx;
+        for (int64_t gS1Index = runParam.gs1LoopStartIdx; gS1Index < gS1LoopEnd; gS1Index++) {
+            bool notLastTwoLoop = true;
+            if (lastBN) {
+                int32_t extraGS1 = gS1Index - runParam.gs1LoopEndIdx;
+                switch (extraGS1) {
+                    case 0:
+                        notLastTwoLoop = false;
+                        break;
+                    case 1:
+                        notLast = false;
+                        notLastTwoLoop = false;
+                        break;
+                    default:
+                        break;
+                }
+            }
+            if (notLastTwoLoop) {
+                this->ComputeAxisIdxByBnAndGs1(bnIdx, gS1Index, runParam);
+                bool s1NoNeedCalc = ComputeParamS1<TEMPLATE_INTF_ARGS>(
+                    runParam, this->constInfo, gS1Index, this->actualSeqQlenAddr);
+                // Continue when either S1 or S2 requires no computation. On the current core's final iteration,
+                // also complete the taskIdx + 2 work.
+                bool s2NoNeedCalc =
+                    ComputeS2LoopInfo<TEMPLATE_INTF_ARGS>(runParam, this->constInfo);
+                if (s1NoNeedCalc || s2NoNeedCalc) {
+                    continue;
+                }
+                s2LoopLimit = runParam.s2LoopEndIdx - 1;
+                if constexpr (IS_SPLIT_G) {
+                    maxS2LoopCnt -= (s2LoopLimit + 1);
+                }
+            } else {
+                s2LoopLimit = 0;
+            }
+            for (int64_t s2LoopCount = 0; s2LoopCount <= s2LoopLimit; ++s2LoopCount) {
+                if (notLastTwoLoop) {
+                    RunInfo &runInfo1 = runInfo[taskId % 3];
+                    this->SetRunInfo(runInfo1, runParam, taskId, s2LoopCount, s2LoopLimit, multiCoreInnerIdx);
+                    if ASCEND_IS_AIC {
+                        this->cubeBlock.IterateBmm1(this->bmm1Buffers.Get(),
+                            this->l1RightBuffers.Get(), v0ResGmBuffers.Get(), runInfo1, this->constInfo);
+                    } else {
+                        this->vecBlock.ProcessVec0(this->l1RightBuffers.Get(), v0ResGmBuffers.Get(),
+                            runInfo1, this->constInfo, 0);
+                    }
+                } else {
+                    if ASCEND_IS_AIV {
+                        if constexpr (IS_SPLIT_G) {
+                            if (maxS2LoopCnt > 0) {
+                                maxS2LoopCnt--;
+                                CrossCoreSetFlag<0, PIPE_MTE3>(15);
+                                CrossCoreWaitFlag<0, PIPE_MTE3>(15);
+                            }
+                        }
+                    }
+                }
+                if (taskId > 0 && notLast) {
+                    auto &runInfo2 = runInfo[(taskId + 2) % 3];
+                    if ASCEND_IS_AIV {
+                        this->vecBlock.ProcessVec1(this->l1RightBuffers.GetReused(),
+                            this->bmm1Buffers.Get(), runInfo2, this->constInfo);
+                    } else {
+                        RunInfo &runInfo2 = runInfo[(taskId + 2) % 3];
+                        this->cubeBlock.IterateBmm2(this->bmm2Buffers.Get(), this->l1RightBuffers,
+                            this->l1RightBuffers.GetReused(), runInfo2, this->constInfo);
+                    }
+                }
+                if (taskId > 1) {
+                    if ASCEND_IS_AIV {
+                        RunInfo &runInfo3 = runInfo[(taskId + 1) % 3];
+                        this->vecBlock.ProcessVec2(this->bmm2Buffers.Get(), runInfo3, this->constInfo);
+                    }
+                }
+                ++taskId;
+            }
+            ++multiCoreInnerIdx;
+        }
+        gS1StartIdx = 0;
+    }
+    if ASCEND_IS_AIV {
+        if constexpr (IS_SPLIT_G) {
+            for (int64_t loopCnt = 0; loopCnt < maxS2LoopCnt; loopCnt++) {
+                CrossCoreSetFlag<0, PIPE_MTE3>(15);
+                CrossCoreWaitFlag<0, PIPE_MTE3>(15);
+            }
+        }
+    }
+}
+
+template <typename CubeBlockType, typename VecBlockType>
+__aicore__ inline void FusedSparseAttentionOverlapKernelMla<CubeBlockType, VecBlockType>::ComputeAxisIdxByBnAndGs1(
+    int64_t bnIndex, int64_t gS1Index, RunParamStr &runParam)
+{
+    // Merge the G and S1 axes; do not split G, only split S1.
+    runParam.s1oIdx = gS1Index * runParam.qSNumInOneBlock;
+    if constexpr (IS_SPLIT_G) {
+        runParam.goIdx = (aicIdx % 2 == 0) ? 0 : 64; // For N1=128, adjacent Cube cores process one S1: the first handles G rows 0-63 and the second handles the remaining 64 rows
+    } else {
+        runParam.goIdx = 0;
+    }
+}
+
+template <typename CubeBlockType, typename VecBlockType>
+__aicore__ inline void FusedSparseAttentionOverlapKernelMla<CubeBlockType, VecBlockType>::SetRunInfo(
+    RunInfo &runInfo, RunParamStr &runParam, int64_t taskId, int64_t s2LoopCount,
+    int64_t s2LoopLimit, int64_t multiCoreInnerIdx)
+{
+    if (s2LoopCount < runParam.kvLoopEndIdx) {
+        runInfo.s2StartIdx = runParam.s2LineStartIdx;
+        runInfo.s2EndIdx = runParam.s2LineEndIdx;
+    }
+    runInfo.s2LoopCount = s2LoopCount;
+    if (runInfo.multiCoreInnerIdx != multiCoreInnerIdx) {
+        runInfo.s1oIdx = runParam.s1oIdx;
+        runInfo.boIdx = runParam.boIdx;
+        runInfo.n2oIdx = runParam.n2oIdx;
+        runInfo.goIdx = runParam.goIdx;
+        runInfo.multiCoreInnerIdx = multiCoreInnerIdx;
+        runInfo.multiCoreIdxMod2 = multiCoreInnerIdx & 1;
+        runInfo.multiCoreIdxMod3 = multiCoreInnerIdx % 3;
+    }
+
+    runInfo.taskId = taskId;
+    runInfo.taskIdMod2 = taskId & 1;
+    runInfo.taskIdMod3 = taskId % 3;
+    runInfo.s2LoopLimit = s2LoopLimit;
+
+    runInfo.actualS1Size = runParam.actualS1Size;
+    runInfo.actualS2Size = runParam.actualS2Size;
+    runInfo.attentionOutOffset = runParam.attentionOutOffset;
+    runInfo.sOuterOffset = runParam.sOuterOffset;
+    runInfo.queryOffset = runParam.tensorQOffset;
+    this->ComputeBmm1Tail(runInfo, runParam);
+    InitUniqueRunInfo(runParam, runInfo);
+}
+
+template <typename CubeBlockType, typename VecBlockType>
+__aicore__ inline void FusedSparseAttentionOverlapKernelMla<CubeBlockType, VecBlockType>::InitUniqueRunInfo(
+    const RunParamStr &runParam, RunInfo &runInfo)
+{
+    InitTaskParamByRun<TEMPLATE_INTF_ARGS>(runParam, runInfo);
+}
+
+template <typename CubeBlockType, typename VecBlockType>
+__aicore__ inline void FusedSparseAttentionOverlapKernelMla<CubeBlockType, VecBlockType>::ComputeBmm1Tail(
+    RunInfo &runInfo, RunParamStr &runParam)
+{
+    // ------------------------S1 Base Related---------------------------
+    runInfo.s1RealSize = runParam.s1RealSize;
+    runInfo.halfS1RealSize = runParam.halfS1RealSize;
+    runInfo.firstHalfS1RealSize = runParam.firstHalfS1RealSize;
+    runInfo.mRealSize = runParam.mRealSize;
+    runInfo.halfMRealSize = runParam.halfMRealSize;
+    runInfo.firstHalfMRealSize = runParam.firstHalfMRealSize;
+
+    runInfo.vec2S1BaseSize = runInfo.halfS1RealSize;
+    runInfo.vec2MBaseSize = runInfo.halfMRealSize;
+
+    // ------------------------S2 Base Related----------------------------
+    runInfo.s2RealSize = constInfo.s2BaseSize;
+    runInfo.s2AlignedSize = runInfo.s2RealSize;
+    int64_t curS2LoopCnt = runInfo.s2LoopCount;
+    if (runInfo.s2StartIdx + (curS2LoopCnt + 1) * runInfo.s2RealSize > runInfo.s2EndIdx) {
+        runInfo.s2RealSize = runInfo.s2EndIdx - curS2LoopCnt * runInfo.s2RealSize - runInfo.s2StartIdx;
+        runInfo.s2AlignedSize = Align(runInfo.s2RealSize);
+    }
+}
+}
